// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListDrinks List drink presets
	// (GET /drinks)
	ListDrinks(ctx context.Context, request ListDrinksRequestObject) (ListDrinksResponseObject, error)
	// CreateDrink Add a custom drink preset
	// (POST /drinks)
	CreateDrink(ctx context.Context, request CreateDrinkRequestObject) (CreateDrinkResponseObject, error)
	// SearchGames Search the Steam store by name
	// (GET /games)
	SearchGames(ctx context.Context, request SearchGamesRequestObject) (SearchGamesResponseObject, error)
	// Login Log in, registering the username if it is new
	// (POST /login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// ListParties List parties, newest first
	// (GET /parties)
	ListParties(ctx context.Context, request ListPartiesRequestObject) (ListPartiesResponseObject, error)
	// CreateParty Create a party with a generated 6-character code
	// (POST /parties)
	CreateParty(ctx context.Context, request CreatePartyRequestObject) (CreatePartyResponseObject, error)
	// GetParty Get the full state of a party
	// (GET /parties/{code})
	GetParty(ctx context.Context, request GetPartyRequestObject) (GetPartyResponseObject, error)
	// JoinParty Add a user to the party (idempotent)
	// (PUT /parties/{code}/attendees/{username})
	JoinParty(ctx context.Context, request JoinPartyRequestObject) (JoinPartyResponseObject, error)
	// AddBeer Count one more beer for an attendee
	// (POST /parties/{code}/beers)
	AddBeer(ctx context.Context, request AddBeerRequestObject) (AddBeerResponseObject, error)
	// AddOption Nominate a game (only during NOMINATION)
	// (POST /parties/{code}/options)
	AddOption(ctx context.Context, request AddOptionRequestObject) (AddOptionResponseObject, error)
	// RemoveOption Remove a nominated game (only during NOMINATION)
	// (DELETE /parties/{code}/options/{name})
	RemoveOption(ctx context.Context, request RemoveOptionRequestObject) (RemoveOptionResponseObject, error)
	// SetPartyStatus Move the party to another phase
	// (PUT /parties/{code}/status)
	SetPartyStatus(ctx context.Context, request SetPartyStatusRequestObject) (SetPartyStatusResponseObject, error)
	// StreamParty Server-Sent Events stream for live party updates
	// (GET /parties/{code}/stream)
	StreamParty(ctx context.Context, request StreamPartyRequestObject) (StreamPartyResponseObject, error)
	// SubmitVotes Submit (or replace) a user's votes for the current round
	// (PUT /parties/{code}/votes/{username})
	SubmitVotes(ctx context.Context, request SubmitVotesRequestObject) (SubmitVotesResponseObject, error)
	// ListUsers List all registered users
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

